diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -1173,8 +1173,6 @@ callUnknownEncodingRelease(XML_Parser parser) {
   beforeHandler(parser);
   parser->m_unknownEncodingRelease(parser->m_unknownEncodingData);
   afterHandler(parser);
-  parser->m_unknownEncodingRelease = NULL;
-  parser->m_unknownEncodingData = NULL;
 }

 static int XMLCALL
@@ -4969,9 +4967,11 @@ handleUnknownEncoding(XML_Parser parser, const XML_Char *encodingName) {
       ENCODING *enc;
       parser->m_unknownEncodingMem = MALLOC(parser, XmlSizeOfUnknownEncoding());
       if (! parser->m_unknownEncodingMem) {
-        if (parser->m_unknownEncodingRelease)
+        if (parser->m_unknownEncodingRelease) {
           callUnknownEncodingRelease(parser);
-        else
+          parser->m_unknownEncodingRelease = NULL;
+          parser->m_unknownEncodingData = NULL;
+        } else
           parser->m_unknownEncodingData = NULL;
         return XML_ERROR_NO_MEMORY;
       }
@@ -4985,9 +4985,11 @@ handleUnknownEncoding(XML_Parser parser, const XML_Char *encodingName) {
       }
       parser->m_unknownEncodingConvert = NULL;
     }
-    if (parser->m_unknownEncodingRelease != NULL)
+    if (parser->m_unknownEncodingRelease != NULL) {
       callUnknownEncodingRelease(parser);
-    else
+      parser->m_unknownEncodingRelease = NULL;
+      parser->m_unknownEncodingData = NULL;
+    } else
       parser->m_unknownEncodingData = NULL;
   }
   return XML_ERROR_UNKNOWN_ENCODING;

diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -1537,8 +1537,6 @@ parserInit(XML_Parser parser, const XML_Char *encodingName) {
   parser->m_nSpecifiedAtts = 0;
   parser->m_unknownEncodingMem = NULL;
   parser->m_unknownEncodingConvert = NULL;
-  parser->m_unknownEncodingRelease = NULL;
-  parser->m_unknownEncodingData = NULL;
   parser->m_parsingStatus.parsing = XML_INITIALIZED;
   // Reentry can only be triggered inside m_processor calls
   parser->m_reenter = XML_FALSE;

diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -1176,6 +1176,13 @@ callUnknownEncodingRelease(XML_Parser parser) {
   parser->m_unknownEncodingData = NULL;
 }

+static void
+callUnknownEncodingReleaseBeforeTeardown(XML_Parser parser) {
+  beforeHandler(parser);
+  parser->m_unknownEncodingRelease(parser->m_unknownEncodingData);
+  afterHandler(parser);
+}
+
 static int XMLCALL
 callUnknownEncodingConvert(void *data, const char *p) {
   XML_Parser parser = data;
@@ -1582,7 +1589,7 @@ XML_ParserReset(XML_Parser parser, const XML_Char *encodingName) {
   // The application-defined release callback may access the parser, so it
   // must run before any parser state is freed.
   if (parser->m_unknownEncodingRelease)
-    callUnknownEncodingRelease(parser);
+    callUnknownEncodingReleaseBeforeTeardown(parser);
   /* move m_tagStack to m_freeTagList */
   tStk = parser->m_tagStack;
   while (tStk) {
@@ -1848,7 +1855,7 @@ XML_ParserFree(XML_Parser parser) {
   // The application-defined release callback may access the parser, so it
   // must run before any parser state is freed.
   if (parser->m_unknownEncodingRelease)
-    callUnknownEncodingRelease(parser);
+    callUnknownEncodingReleaseBeforeTeardown(parser);
   /* free m_tagStack and m_freeTagList */
   tagList = parser->m_tagStack;
   for (;;) {
